@push('scripts')<script>
const categoryModal=document.querySelector('[data-category-modal]'),categoryBackdrop=document.querySelector('[data-category-backdrop]'),categoriesUrl=@json(route('admin.categories.index')),hasEditingCategory=@json((bool)$editingCategory);const openCategoryModal=()=>{categoryModal.style.transform='translate(-50%,-50%)';categoryModal.classList.remove('pointer-events-none','opacity-0');categoryBackdrop.classList.remove('hidden');document.body.classList.add('overflow-hidden')};const closeCategoryModal=()=>{if(hasEditingCategory){window.location.href=categoriesUrl;return}categoryModal.style.transform='translate(-50%,-45%)';categoryModal.classList.add('pointer-events-none','opacity-0');categoryBackdrop.classList.add('hidden');document.body.classList.remove('overflow-hidden')};document.addEventListener('click',e=>{if(e.target.closest('[data-open-category-modal]')){if(hasEditingCategory)window.location.href=categoriesUrl;else openCategoryModal()}});document.querySelectorAll('[data-close-category-modal]').forEach(b=>b.addEventListener('click',closeCategoryModal));categoryBackdrop?.addEventListener('click',closeCategoryModal);@if($editingCategory||$errors->any())openCategoryModal();@endif
</script>@endpush
